using Ume.Rag.Domain;
using Ume.Rag.Pipelines.Processing;

namespace Ume.Rag.Worker.Processing.Persistence;

// The tables processing reads and writes (data-model §2.1, §2.2, §3.2; columns as in stream B's ingestion schema, PR #76),
// behind interfaces so the stages and their tests run without the database. The SQL implementations come with the engine
// and the index writer (P1a item 9, after J2): vectors (Chunks."Embedding", EmbeddingCache."Embedding",
// EmbeddingProfiles."CanaryEmbedding") are unmapped `vector` columns written through SQL; Chunks."SearchVector" is
// generated by the database from SearchText.

/// <summary><c>content."NodeOutputs"</c>: the stage output cache index (engine design §8).</summary>
public sealed record NodeOutputRecord(byte[] CacheKey, string Classification, string NodeType, int NodeVersion, byte[] ParamsHash,
    byte[] InputHash, byte[] OutputHash, string BlobPath, bool IsParseOutput, DateTimeOffset CreatedAt, DateTimeOffset LastUsedAt);

public interface INodeOutputStore
{
    Task<NodeOutputRecord?> FindAsync(byte[] cacheKey, CancellationToken cancellationToken);

    /// <summary><c>INSERT … ON CONFLICT ("CacheKey") DO NOTHING</c>; false when the key already existed.</summary>
    Task<bool> TryAddAsync(NodeOutputRecord output, CancellationToken cancellationToken);

    /// <summary>Extends <c>LastUsedAt</c> at most once a day per row (engine design §8).</summary>
    Task TouchAsync(byte[] cacheKey, DateTimeOffset now, CancellationToken cancellationToken);
}

/// <summary><c>config."EmbeddingProfiles"</c> as the embed stage reads it (data-model §2.1; <c>MaxResidency</c> per P1 README §8 O1).</summary>
public sealed record EmbeddingProfileRecord(Guid Id, string Name, string GatewayModel, int Dimensions, int MaxInputTokens, Residency MaxResidency)
{
    public string Distance { get; init; } = "cosine";

    public string? CanaryText { get; init; }

    /// <summary>The recorded canary vector (item 13 seeds it from the gateway); null = not recorded.</summary>
    public IReadOnlyList<float>? CanaryEmbedding { get; init; }

    public bool IsDefault { get; init; }

    public string State { get; init; } = "active";

    /// <summary>Send <c>"dimensions": Dimensions</c> on every embedding call (U-b, #142); false for BGE-M3 (gateway-changes §6).</summary>
    public bool RequestDimensions { get; init; }

    /// <summary>The <c>dimensions</c> to send, or null when the profile must not send it.</summary>
    public int? DimensionsParameter => RequestDimensions ? Dimensions : null;
}

public interface IEmbeddingProfileStore
{
    Task<EmbeddingProfileRecord?> GetAsync(Guid profileId, CancellationToken cancellationToken);

    /// <summary>Active profiles with a canary, for the canary check.</summary>
    Task<IReadOnlyList<EmbeddingProfileRecord>> ActiveAsync(CancellationToken cancellationToken);
}

/// <summary><c>content."EmbeddingCache"</c>: (level, profile, <c>TextHash</c>) → vector (processing design §11).</summary>
public interface IEmbeddingCache
{
    /// <summary>One <c>SELECT … WHERE "Classification" = @l AND "EmbeddingProfileId" = @p AND "TextHash" = ANY(@h)</c>.</summary>
    Task<IReadOnlyDictionary<string, float[]>> GetAsync(string classification, Guid profileId, IReadOnlyCollection<string> textHashes, CancellationToken cancellationToken);

    /// <summary>Its own short transaction, <c>ON CONFLICT DO NOTHING</c>.</summary>
    Task PutAsync(string classification, Guid profileId, IReadOnlyDictionary<string, float[]> vectors, DateTimeOffset now, CancellationToken cancellationToken);

    /// <summary><c>LastUsedAt</c> touched at most once a day per row.</summary>
    Task TouchAsync(string classification, Guid profileId, IReadOnlyCollection<string> textHashes, DateTimeOffset now, CancellationToken cancellationToken);
}

/// <summary><c>content."ParseObservations"</c> (processing design §3.5; retention 180 days).</summary>
public sealed record ParseObservationRecord(Guid Id, string Classification, Guid DocumentId, string Domain, string PathPattern, string? DocumentType,
    string? Strategy, decimal Score, string? Metrics, DateTimeOffset ObservedAt);

public interface IParseObservationStore
{
    Task AddAsync(ParseObservationRecord observation, CancellationToken cancellationToken);
}

/// <summary>The unique key of <c>content."ChunkSets"</c> (engine design §14).</summary>
public sealed record ChunkSetKey(Guid DocumentId, Guid PipelineVersionId, Guid? SiteProfileVersionId, Guid EmbeddingProfileId, byte[] ContentHash);

/// <summary><c>ChunkSets."State"</c> values (data-model §2.2).</summary>
public static class ChunkSetState
{
    public const string Writing = "writing";
    public const string Live = "live";
    public const string Held = "held";
    public const string Superseded = "superseded";
}

/// <summary>A row of <c>content."ChunkSets"</c>.</summary>
public sealed record ChunkSetRecord(Guid Id, ChunkSetKey Key, string Classification, Guid CollectionId, byte[] InputHash)
{
    /// <summary><c>StageKeys jsonb</c>: the keys and output hashes the set was built from (engine design §3.3).</summary>
    public string? StageKeys { get; init; }

    public string State { get; init; } = ChunkSetState.Writing;

    public bool PiiFlagged { get; init; }

    public PiiCounts? PiiCounts { get; init; }

    public int ChunkCount { get; init; }

    public DateTimeOffset CreatedAt { get; init; }

    public DateTimeOffset? LiveAt { get; init; }

    public DateTimeOffset? SupersededAt { get; init; }
}

/// <summary>A row of <c>content."Chunks"</c> (flat child chunks; data-model §2.2, §3.2).</summary>
public sealed record ChunkRecord(Guid Id, Guid ChunkSetId, Guid DocumentId, Guid CollectionId, string Classification, int Ordinal, ChunkDraft Draft, Guid EmbeddingProfileId, float[] Embedding)
{
    public string Kind { get; init; } = "child";

    /// <summary>A chunk is searchable iff this is null.</summary>
    public DateTimeOffset? DeletedAt { get; init; }
}

/// <summary>The clearance on <c>content."Documents"</c> (<c>PiiClearedAt</c>, <c>PiiClearedBy</c>, <c>PiiClearedCounts</c>).</summary>
public sealed record PiiClearance(DateTimeOffset ClearedAt, string ClearedBy, PiiCounts Counts);

/// <summary>
/// The chunk-set side the personal-data lifecycle needs (processing design §9.5; engine design §14 rules 2–3). The SQL
/// implementation is the index writer's (item 9): one fenced transaction per swap.
/// </summary>
public interface IChunkSetStore
{
    /// <summary>Inserts the set as <c>writing</c> with its chunks invisible (<c>DeletedAt</c> set).</summary>
    Task InsertWritingAsync(ChunkSetRecord set, IReadOnlyList<ChunkRecord> chunks, CancellationToken cancellationToken);

    Task<ChunkSetRecord?> GetAsync(Guid chunkSetId, CancellationToken cancellationToken);

    /// <summary>The set the document's <c>LiveChunkSetId</c> points to (<c>live</c> or <c>held</c>), or null.</summary>
    Task<ChunkSetRecord?> GetCurrentAsync(Guid documentId, CancellationToken cancellationToken);

    /// <summary>
    /// The swap: <c>LiveChunkSetId</c> → the set, which becomes <paramref name="state"/> (<c>live</c> with its chunks'
    /// <c>DeletedAt</c> cleared, or <c>held</c> with them kept deleted); the previous set → <c>superseded</c> with its chunks deleted.
    /// </summary>
    Task SwapAsync(Guid chunkSetId, string state, DateTimeOffset now, CancellationToken cancellationToken);

    /// <summary>Sets <c>live</c> or <c>held</c> on the current set without a new swap (release after a clearance, sweep).</summary>
    Task SetStateAsync(Guid chunkSetId, string state, DateTimeOffset now, CancellationToken cancellationToken);

    /// <summary>Rewrites the set's personal-data state (the sweep's re-run of <c>personal-data</c> for a <c>pending</c> set).</summary>
    Task UpdatePiiAsync(Guid chunkSetId, PiiCounts counts, bool flagged, CancellationToken cancellationToken);

    Task<PiiClearance?> GetClearanceAsync(Guid documentId, CancellationToken cancellationToken);

    Task SetClearanceAsync(Guid documentId, PiiClearance clearance, CancellationToken cancellationToken);

    /// <summary>Current sets whose names are still unchecked (<c>PiiCounts.ner = pending</c>), for the nightly sweep.</summary>
    Task<IReadOnlyList<ChunkSetRecord>> PendingNerAsync(int limit, CancellationToken cancellationToken);

    /// <summary>The chunks of a set in ordinal order.</summary>
    Task<IReadOnlyList<ChunkRecord>> ChunksAsync(Guid chunkSetId, CancellationToken cancellationToken);
}
